def median_absolute_deviation(nums):
    def median(values):
        s = sorted(values)
        n = len(s)
        mid = n // 2
        if n % 2 == 1:
            return float(s[mid])
        return (s[mid - 1] + s[mid]) / 2
    m = median(nums)
    deviations = [abs(x - m) for x in nums]
    return median(deviations)

