def mask_phone_with_ext(phone_ext):
    if ' x' in phone_ext:
        pos = phone_ext.index(' x')
        main = phone_ext[:pos]
        ext = phone_ext[pos:]
    else:
        main = phone_ext
        ext = ''
    digits = [c for c in main if c != '-']
    total = len(digits)
    keep = 4
    masked_digits = []
    for i in range(total):
        if i < total - keep:
            masked_digits.append('*')
        else:
            masked_digits.append(digits[i])
    result = []
    di = 0
    for c in main:
        if c == '-':
            result.append('-')
        else:
            result.append(masked_digits[di])
            di += 1
    return ''.join(result) + ext

