def longest_alternating_substring_length(s):
    if len(s) == 0:
        return 0
    longest = 1
    run = 1
    idx = 1
    while idx < len(s):
        if s[idx] != s[idx - 1]:
            run += 1
        else:
            run = 1
        if run > longest:
            longest = run
        idx += 1
    return longest

def count_char_categories(s):
    categories = {"digits": 0, "letters": 0, "spaces": 0, "other": 0}
    checks = [("digits", str.isdigit), ("letters", str.isalpha), ("spaces", str.isspace)]
    for ch in s:
        for name, pred in checks:
            if pred(ch):
                categories[name] += 1
                break
        else:
            categories["other"] += 1
    return categories

def integer_cube_root(n):
